from Crypto.Cipher import DES
import binascii

def duck(aChr):
    try:
        return int(aChr)
    except ValueError:
        return "abcdef".index(aChr) + 11

def reverse_encodeText(encodedText, offset):
    nibble_len = len(str(offset + 99))  # Ensure maximum nibble length is used
    decoded_hex = ""
    for i in range(0, len(encodedText), nibble_len * 2):
        byte_pair = encodedText[i:i + nibble_len * 2]
        high_nibble = int(byte_pair[:nibble_len]) - offset
        low_nibble = int(byte_pair[nibble_len:]) - offset
        decoded_hex += "abcdef"[high_nibble - 10] if high_nibble >= 10 else str(high_nibble)
        decoded_hex += "abcdef"[low_nibble - 10] if low_nibble >= 10 else str(low_nibble)
    return binascii.unhexlify(decoded_hex)

def depad_input(padded):
    return padded.rstrip("_")

def des_decrypt(input_bytes, key):
    IV = b'13371337'  # Use IV as bytes
    cipher = DES.new(key, DES.MODE_OFB, IV)
    plaintext = cipher.decrypt(input_bytes)
    return depad_input(plaintext.decode())

def read_file(path):
    with open(path, 'r') as f:
        return f.read()

def main():
